"""Article-specific editorial source for CC-08 (Civil Code arts. 461-520)."""
from __future__ import annotations


def row(says, means, example, warning, term, definition, *, target=None, terms=None):
    return {
        "target": target,
        "o_que_diz": says,
        "o_que_significa": means,
        "exemplo_pratico": example,
        "atencao": warning,
        "palavras_dificeis": terms or [{"termo": term, "explicacao": definition}],
    }


ROWS = {
    "461": row("A venda aleatória pode ser anulada por dolo quando o prejudicado demonstrar que a outra parte sabia que o risco já havia se consumado.", "O contratante não pode negociar como incerto um resultado que conhece como já definido. A anulação exige prova desse conhecimento e do prejuízo.", "Vendedor negocia safra supostamente sujeita a risco, embora saiba que ela já foi destruída.", "A simples frustração do resultado não basta. Devem ser provados a consumação anterior do risco, a ciência da contraparte e o dolo.", "Alienação aleatória", "negócio em que a existência ou quantidade da coisa depende de risco assumido"),
    "462": row("O contrato preliminar deve reunir os elementos essenciais do contrato futuro, mas não precisa adotar a forma exigida para o definitivo.", "A promessa precisa identificar conteúdo suficiente para permitir a celebração posterior. A dispensa legal recai sobre a forma, não sobre objeto, partes e demais requisitos essenciais.", "Promessa de venda identifica imóvel, preço e contratantes, embora ainda não seja lavrada por escritura pública.", "A regra não elimina formalidades necessárias ao contrato definitivo nem sana objeto ilícito ou indeterminado.", "Contrato preliminar", "acordo pelo qual as partes assumem o dever de celebrar outro contrato"),
    "463": row("Sem cláusula de arrependimento, qualquer parte pode exigir o contrato definitivo e fixar prazo para a outra concluí-lo; o preliminar deve ser registrado no órgão competente.", "O acordo válido cria pretensão ao cumprimento específico. O registro dá publicidade e relevância perante terceiros, enquanto a ausência de arrependimento confirma a vinculação.", "Promitente comprador notifica o vendedor para assinar o contrato definitivo em prazo determinado.", "A exigência pressupõe os requisitos do art. 462. Cláusula válida de arrependimento altera a possibilidade de compelir a contratação.", "Cláusula de arrependimento", "previsão que permite desfazer o compromisso nas condições pactuadas"),
    "464": row("Vencido o prazo sem celebração, o juiz pode, a pedido do interessado, substituir a manifestação do inadimplente e tornar definitivo o contrato preliminar.", "A tutela específica evita que a recusa injustificada impeça o resultado prometido. Ela não se aplica quando a própria natureza da obrigação exigir manifestação pessoal insubstituível.", "Vendedor se recusa a formalizar a venda prometida; decisão judicial supre sua vontade e consolida o negócio.", "O efeito não é automático: depende de pedido, inadimplemento e compatibilidade da obrigação com o suprimento judicial.", "Suprimento de vontade", "substituição judicial da declaração que a parte tinha dever de emitir"),
    "465": row("Se quem prometeu contratar não cumprir o contrato preliminar, a outra parte pode desfazê-lo e cobrar perdas e danos.", "Além de buscar a celebração definitiva quando cabível, o credor pode optar pelo encerramento do vínculo e pela reparação dos prejuízos causados pela inexecução.", "Promitente vendedor abandona o compromisso; o comprador resolve a promessa e pede ressarcimento das despesas comprovadas.", "A indenização exige dano e nexo causal e não pode duplicar valores já restituídos. A escolha deve respeitar boa-fé e regras do inadimplemento.", "Estipulante", "parte que assume no contrato preliminar o compromisso de celebrar o definitivo"),
    "466": row("Na promessa unilateral, o beneficiário deve declarar que pretende contratar dentro do prazo previsto ou daquele razoavelmente fixado pelo promitente.", "Como apenas uma parte está inicialmente vinculada, a omissão do credor dentro do prazo faz a promessa perder eficácia. A manifestação transforma a faculdade em contratação exigível conforme o ajuste.", "Proprietário concede opção de compra por trinta dias; o interessado precisa exercê-la nesse período.", "Sem prazo contratual, o devedor deve assinar período razoável. Não se presume exercício apenas pelo silêncio do beneficiário.", "Promessa unilateral", "compromisso em que só uma parte fica obrigada até a manifestação da outra"),
    "467": row("Ao concluir o contrato, uma parte pode reservar o direito de indicar depois quem receberá os direitos e assumirá as obrigações.", "O negócio nasce entre os contratantes originais, mas admite substituição posterior por pessoa nomeada conforme as regras seguintes. A reserva deve integrar o contrato desde sua formação.", "Comprador celebra aquisição e reserva a faculdade de indicar sociedade que ocupará sua posição contratual.", "Não se trata de indicação livre a qualquer tempo. Prazo, forma, aceitação, capacidade e solvência do nomeado precisam ser observados.", "Pessoa a declarar", "terceiro que poderá substituir contratante por indicação prevista desde o acordo"),
    "468": row("A nomeação deve ser comunicada em cinco dias após o contrato, salvo prazo diferente; a aceitação do indicado precisa observar a mesma forma usada no negócio.", "A substituição exige comunicação tempestiva e concordância formalmente compatível, assegurando certeza sobre quem ocupará a posição contratual.", "Contrato escrito prevê pessoa a declarar; o indicado aceita por escrito e é comunicado no prazo ajustado.", "Nomeação e aceitação são atos distintos. Falha no prazo ou na forma pode manter os efeitos apenas entre os contratantes originários.", "Nomeação", "indicação da pessoa que ingressará na posição contratual reservada"),
    "469": row("A pessoa validamente nomeada recebe direitos e obrigações desde a data em que o contrato original foi celebrado.", "A substituição produz efeito retroativo: juridicamente, o nomeado passa a ocupar a posição contratual desde o início, e não apenas a partir da comunicação.", "Sociedade indicada depois assume, desde a assinatura original, direitos e deveres da compra realizada com reserva de nomeação.", "A retroação depende do cumprimento dos arts. 467 e 468. Ela não convalida indicação tardia, aceitação defeituosa, incapacidade ou insolvência relevante.", "Efeito retroativo", "efeito jurídico projetado para momento anterior ao ato que o confirmou"),
    "470": row("O contrato permanece apenas entre os participantes originais se ninguém for indicado, se o nomeado recusar ou se ele for insolvente e a outra parte ignorava isso ao receber a indicação.", "Nessas situações, a substituição não se completa. O contratante que reservou a nomeação continua responsável perante a contraparte.", "Comprador indica empresa insolvente sem que o vendedor conheça a situação; o comprador original permanece no contrato.", "A insolvência deve existir na situação relevante e ser desconhecida pela outra parte. Este artigo não extingue automaticamente o contrato.", "Contratantes originários", "pessoas que celebraram inicialmente o negócio com reserva de nomeação"),
    "471": row("Se o indicado era incapaz ou insolvente quando foi nomeado, os efeitos do contrato ficam entre as partes originais.", "A lei protege a contraparte contra substituição por pessoa sem capacidade jurídica adequada ou sem solvência. A tentativa de nomeação não libera o contratante inicial.", "Pessoa indica menor sem representação válida para assumir compra; a relação continua vinculando os contratantes originários.", "Capacidade e insolvência são examinadas no momento da nomeação. Regras de representação e o conhecimento da contraparte também podem ser juridicamente relevantes.", "Incapaz", "pessoa que não pode praticar sozinha certos atos civis segundo a lei"),
    "472": row("O distrato deve observar a mesma forma que a lei exigiu para o contrato desfeito.", "As partes podem extinguir consensualmente o vínculo, mas precisam repetir a forma legal obrigatória do negócio original. Forma apenas escolhida pelas partes não se confunde necessariamente com forma exigida.", "Venda imobiliária feita por escritura pública é desfeita mediante instrumento com a forma legal correspondente.", "O artigo disciplina a forma do distrato; restituições, direitos de terceiros e efeitos já produzidos ainda precisam ser resolvidos.", "Distrato", "acordo pelo qual as partes encerram contrato anteriormente celebrado"),
    "473": row("Quando admitida por lei, a resilição unilateral ocorre por denúncia comunicada à outra parte; investimentos relevantes podem exigir prazo compatível antes de produzir efeitos.", "A parte pode terminar certos contratos sem inadimplemento, mas deve notificar. A proteção dos investimentos evita ruptura imediata que frustre gastos consideráveis feitos para executar o acordo.", "Distribuidor investe em estrutura específica; a denúncia só se torna eficaz após período adequado à recuperação do investimento.", "A faculdade precisa ser legalmente permitida. O prazo protetivo depende da natureza do contrato e do vulto comprovado dos investimentos.", "Resilição unilateral", "extinção do contrato por vontade de uma parte nos casos admitidos"),
    "474": row("A cláusula resolutiva expressa produz resolução de pleno direito; a implícita exige interpelação judicial.", "Se o contrato declara claramente o evento resolutivo, sua ocorrência aciona a consequência pactuada. Sem cláusula expressa, o interessado precisa provocar judicialmente a resolução baseada no inadimplemento.", "Contrato prevê resolução se parcela não for paga; ocorrido o fato, invoca-se a cláusula expressa.", "A expressão de pleno direito não elimina a verificação do fato, boa-fé, eventual purgação admitida ou discussão judicial dos efeitos.", "Cláusula resolutiva", "previsão que autoriza extinguir o contrato diante de evento ou inadimplemento"),
    "475": row("Diante do inadimplemento, a parte prejudicada pode escolher entre resolver o contrato e exigir seu cumprimento, mantendo em ambos os casos a possibilidade de perdas e danos.", "A escolha busca recompor o interesse contratual: encerrar a relação ou obter a prestação. A indenização alcança prejuízos adicionais comprovados.", "Fornecedor não entrega equipamento; o comprador pede resolução e indenização ou exige a entrega mais os danos do atraso.", "Não se admite cumular resolução e cumprimento integral incompatíveis. A gravidade do inadimplemento, o dano e o nexo devem ser demonstrados.", "Resolução", "extinção do contrato em razão de inadimplemento ou outra causa resolutiva"),
    "476": row("Em contrato bilateral, quem ainda não cumpriu sua própria prestação não pode exigir o cumprimento da contraparte.", "A reciprocidade permite suspender a exigência enquanto o demandante permanece inadimplente. A defesa preserva o equilíbrio entre obrigações correspondentes.", "Comprador que não paga a parcela vencida não pode exigir a entrega simultaneamente devida sem oferecer seu pagamento.", "A exceção pressupõe prestações relacionadas e exigíveis. Ordem de cumprimento, adimplemento substancial e inadimplementos de gravidade diferente exigem análise concreta.", "Exceção do contrato não cumprido", "defesa que suspende a exigência enquanto a outra parte não cumpre dever recíproco"),
    "477": row("Se a situação patrimonial de uma parte piorar após o contrato e ameaçar sua prestação, a outra pode suspender o que deve até receber cumprimento ou garantia suficiente.", "A regra antecipa proteção contra risco superveniente de inadimplemento. Não extingue o contrato: permite reter temporariamente a prestação para exigir segurança adequada.", "Vendedor descobre insolvência superveniente do comprador antes da entrega e pede caução para prosseguir.", "É necessária deterioração patrimonial posterior capaz de comprometer a contraprestação. Receio genérico ou condição já conhecida não basta.", "Garantia bastante", "segurança patrimonial suficiente para tornar provável o cumprimento futuro"),
    "478": row("Em contrato continuado ou de execução futura, acontecimento extraordinário e imprevisível que torne uma prestação excessivamente onerosa e gere extrema vantagem à outra parte permite ao devedor pedir resolução.", "O remédio alcança desequilíbrio superveniente excepcional, não simples variação normal do negócio. Decretada judicialmente, a resolução produz efeitos desde a citação.", "Evento imprevisível altera radicalmente o custo de prestação futura e cria vantagem extrema para o credor; o devedor pede resolução.", "Os requisitos são cumulativos. Dificuldade econômica comum, risco assumido ou aumento ordinário não configuram automaticamente onerosidade excessiva.", "Execução diferida", "contrato cuja prestação principal será cumprida em momento futuro"),
    "479": row("O réu pode impedir a resolução por onerosidade excessiva oferecendo ajuste equitativo das condições contratuais.", "Em vez de extinguir o contrato, a contraparte pode restaurar o equilíbrio mediante proposta adequada. A modificação deve enfrentar efetivamente a onerosidade demonstrada.", "Credor oferece reduzir quantidade e rever preço para neutralizar desequilíbrio extraordinário e conservar o contrato.", "Qualquer oferta simbólica não basta. A adequação da proposta é examinada em relação ao desequilíbrio e aos requisitos do art. 478.", "Modificação equitativa", "ajuste proporcional destinado a restabelecer equilíbrio razoável do contrato"),
    "480": row("Em contrato no qual somente uma parte tem obrigações, ela pode pedir redução da prestação ou mudança no modo de cumpri-la para evitar onerosidade excessiva.", "Como não há contraprestação recíproca a resolver, a lei privilegia adaptação do dever unilateral. A medida deve ser suficiente e proporcional ao desequilíbrio superveniente.", "Doador sujeito a encargo extraordinariamente agravado pede redução ou alteração da forma de execução.", "A unilateralidade do contrato e a onerosidade precisam ser demonstradas. O artigo não autoriza simples abandono da obrigação.", "Contrato unilateral", "contrato que cria obrigação principal apenas para uma das partes"),
    "481": row("Na compra e venda, o vendedor assume o dever de transferir o domínio de coisa determinada, e o comprador deve pagar preço em dinheiro.", "O contrato cria obrigações recíprocas; a propriedade não se transfere necessariamente pela assinatura, pois depende do modo legal apropriado, como tradição ou registro.", "Vendedor promete entregar veículo identificado e comprador se obriga a pagar valor monetário ajustado.", "Preço predominantemente não monetário pode caracterizar permuta. Celebração do contrato e transferência do domínio são momentos distintos.", "Domínio", "poder jurídico de propriedade sobre a coisa"),
    "482": row("A compra e venda pura torna-se vinculante quando as partes concordam sobre a coisa e o preço.", "O consenso sobre esses elementos essenciais aperfeiçoa o contrato, ainda que entrega e pagamento ocorram depois. Condição, termo ou formalidade legal podem alterar o momento ou a eficácia.", "Partes acordam qual imóvel será vendido e por qual valor; nasce o vínculo de compra e venda.", "A regra não dispensa forma solene quando exigida nem transfere por si só a propriedade. Objeto e preço devem ser determinados ou determináveis.", "Compra e venda pura", "venda sem condição ou modalidade especial que suspenda sua formação"),
    "483": row("A venda pode abranger coisa existente ou futura; se a futura não surgir, o contrato perde efeito, salvo quando as partes quiseram assumir esse risco em negócio aleatório.", "Na venda futura comum, a existência da coisa é pressuposto de eficácia. No contrato aleatório, o comprador aceita o risco de ela não existir conforme o ajuste.", "Compra de colheita futura fica sem efeito se nada for produzido, salvo assunção expressa do risco da esperança.", "É essencial identificar a intenção contratual. Inexistência por culpa de uma parte pode gerar consequências além da simples ineficácia.", "Coisa futura", "bem que ainda não existe, mas pode vir a existir"),
    "484": row("Na venda baseada em amostra, protótipo ou modelo, o vendedor garante que a coisa terá qualidades correspondentes; em divergência, a referência material prevalece sobre a descrição.", "A amostra funciona como padrão vinculante de conformidade. O comprador pode esperar que o produto entregue reproduza suas características relevantes.", "Tecido é vendido por amostra; o lote entregue deve corresponder à cor e qualidade apresentadas.", "A prevalência resolve contradição com a descrição, mas não elimina especificações compatíveis nem tolerâncias legitimamente pactuadas.", "Protótipo", "exemplar usado como padrão das características do produto contratado"),
    "485": row("As partes podem confiar a um terceiro a definição do preço; se ele recusar, o contrato perde efeito, salvo acordo para nomear substituto.", "O preço continua determinável por critério externo e imparcial. A recusa do avaliador impede a conclusão prática do mecanismo, mas as partes podem preservá-lo escolhendo outra pessoa.", "Comprador e vendedor designam avaliador para fixar o preço de obra de arte; se ele recusa, nomeiam outro por consenso.", "O terceiro não pode ser confundido com uma das partes. A substituição exige acordo, e eventual abuso ou erro segue regras próprias.", "Arbítrio de terceiro", "avaliação confiada a pessoa externa ao contrato para determinar o preço"),
    "486": row("O preço pode ser determinado pela cotação de mercado ou de bolsa em dia e local previamente definidos.", "A lei admite referência objetiva e verificável em vez de valor numérico já escrito. Data e praça escolhidas permitem apurar o preço sem decisão unilateral.", "Contrato de mercadoria usa a cotação da bolsa indicada na data de entrega para calcular o valor.", "O índice deve existir e ser identificável no dia e lugar estipulados. Lacunas ou manipulação podem exigir interpretação e prova.", "Taxa de mercado", "cotação praticada de modo reconhecível em determinado mercado"),
    "487": row("As partes podem calcular o preço por índices ou parâmetros que permitam determinação objetiva.", "A quantia não precisa estar pronta na assinatura, desde que a fórmula dispense vontade exclusiva posterior e conduza a resultado verificável.", "Preço é definido pelo número de unidades entregues multiplicado por índice público indicado no contrato.", "Parâmetro vago ou controlado exclusivamente por uma parte pode tornar o preço inválido. Também devem ser respeitadas normas especiais.", "Parâmetro objetivo", "critério verificável que permite calcular o preço sem escolha arbitrária"),
    "488": row("Sem preço ou critério ajustado e inexistindo tabelamento oficial, aplica-se o valor usual das vendas do vendedor; havendo vários valores, usa-se a média.", "A lei preenche a lacuna com a prática comercial do próprio vendedor, preservando o contrato quando houve intenção de comprar e vender.", "Fornecedor vende produto sem indicar preço, mas costuma negociá-lo entre dois valores; na divergência, apura-se o termo médio.", "A regra é subsidiária. Tabelamento oficial, acordo posterior ou critério já pactuado têm prioridade.", "Preço corrente", "valor normalmente praticado em vendas habituais comparáveis"),
    "489": row("É nula a compra e venda que permita a apenas uma das partes decidir livremente o preço.", "O preço não pode depender de puro arbítrio do comprador ou do vendedor, pois faltaria compromisso objetivo e equilíbrio mínimo na formação do contrato.", "Vendedor se reserva o direito de escolher depois qualquer valor, sem índice ou limite; a venda é nula.", "Critério objetivo influenciado por uma parte não equivale necessariamente a arbítrio exclusivo. A nulidade depende da ausência de parâmetro controlável.", "Arbítrio exclusivo", "poder sem parâmetro de uma parte para definir elemento essencial do negócio"),
    "490": row("Salvo ajuste diverso, o comprador paga escritura e registro, enquanto o vendedor suporta as despesas da entrega.", "A lei distribui custos acessórios por regra supletiva. As partes podem estabelecer divisão diferente no contrato.", "Na venda de imóvel, comprador arca com escritura e registro; vendedor paga custos necessários para entregar o bem, se nada foi convencionado.", "Tributos e despesas regidos por normas especiais não são automaticamente resolvidos por este artigo. Cláusula contratual pode alterar a distribuição.", "Tradição", "entrega juridicamente relevante da coisa ao adquirente"),
    "491": row("Na venda que não seja a crédito, o vendedor pode reter a coisa até receber o preço.", "Pagamento e entrega são prestações simultâneas na venda à vista. O vendedor não precisa adiantar sua parte sem a contraprestação do comprador.", "Comprador exige retirada imediata de equipamento sem pagar o valor à vista; o vendedor pode negar a entrega.", "A regra cede a cláusula ou modalidade que estabeleça crédito. Oferta efetiva de pagamento e mora do vendedor também devem ser consideradas.", "Venda a crédito", "venda em que o pagamento é diferido para momento posterior"),
    "492": row("Antes da entrega, o vendedor suporta o risco da coisa e o comprador o risco do preço; porém bens já disponibilizados podem correr por conta do comprador durante contagem ou medição fortuita e quando ele demora a recebê-los.", "A regra acompanha quem ainda controla cada prestação, com exceções ligadas à individualização e à mora do comprador.", "Mercadoria medida e posta à disposição sofre fortuito durante contagem; o risco pode caber ao comprador.", "É preciso distinguir perda fortuita, culpa, efetiva disponibilização e mora. As exceções não transferem genericamente todo risco antes da tradição.", "Risco da coisa", "responsabilidade econômica pela perda fortuita do bem vendido"),
    "493": row("Sem cláusula específica, a entrega ocorre no local onde a coisa estava quando a venda foi celebrada.", "O lugar originário funciona como regra supletiva e define onde o vendedor deve disponibilizar o bem. As partes podem escolher outro ponto.", "Máquina estava no depósito na data do contrato; sem ajuste de transporte, ali deve ser entregue.", "A regra não decide sozinha quem paga transporte ou suporta riscos de expedição. Convenção e usos aplicáveis podem modificá-la.", "Lugar da tradição", "local em que a entrega juridicamente devida deve ocorrer"),
    "494": row("Se o comprador manda enviar a coisa a outro lugar, o risco passa a ele quando o bem é entregue ao transportador, salvo desobediência do vendedor às instruções.", "A expedição ordenada desloca o risco porque o transporte atende ao comprador. O vendedor continua responsável se alterar indevidamente o modo ou destino indicado.", "Comprador escolhe transportadora; após entrega regular a ela, perda fortuita no trajeto corre por sua conta.", "Culpa do vendedor, embalagem inadequada ou afastamento das instruções impedem aplicação automática da transferência de risco.", "Expedição", "envio da coisa por transportador para local diferente"),
    "495": row("Se o comprador se torna insolvente antes da entrega, o vendedor pode suspendê-la até receber garantia de pagamento, mesmo existindo prazo contratual.", "A deterioração patrimonial supera temporariamente o crédito concedido e protege o vendedor contra entrega sem segurança. Caução adequada restabelece o dever de entregar.", "Comprador entra em insolvência antes de receber mercadoria; vendedor exige garantia para manter o pagamento futuro.", "A insolvência deve anteceder a tradição e comprometer o preço. A medida suspende a entrega, não extingue automaticamente o contrato.", "Caução", "garantia oferecida para assegurar o cumprimento de uma dívida"),
    "496": row("A venda de ascendente para descendente é anulável sem consentimento expresso dos demais descendentes e do cônjuge do vendedor; este último é dispensado na separação obrigatória.", "A regra protege igualdade familiar e evita transmissão disfarçada que prejudique outros interessados. O negócio existe, mas pode ser desconstituído se faltar anuência exigida.", "Pai vende imóvel a um filho sem obter concordância expressa dos outros; a venda pode ser anulada.", "Não se trata de nulidade automática. Devem ser identificados os descendentes relevantes, o regime de bens e as regras de prazo da anulabilidade.", "Consentimento expresso", "anuência manifestada de forma clara, e não presumida pelo silêncio"),
    "497": row("Certas pessoas não podem comprar, nem em leilão, bens ligados à guarda, administração, função pública, processo ou venda que lhes foi confiada; a vedação alcança cessão de crédito.", "O artigo impede conflito de interesses de tutores, administradores, agentes públicos, auxiliares da justiça, leiloeiros e prepostos. A consequência indicada é nulidade.", "Perito não pode comprar bem litigioso submetido à sua atuação no local de sua autoridade.", "A proibição depende do vínculo descrito em cada inciso e de seu alcance territorial ou funcional. Não deve ser ampliada sem base legal.", "Hasta pública", "venda realizada em leilão ou procedimento público de alienação"),
    "498": row("A proibição aplicável a magistrados e auxiliares da justiça não alcança negócio entre coerdeiros, pagamento de dívida ou garantia de bens que já lhes pertencem.", "As exceções permitem operações com causa própria e preexistente, apesar do vínculo funcional mencionado no artigo anterior.", "Juiz que também é coerdeiro pode participar da divisão onerosa do bem hereditário nas condições legais.", "A exceção é limitada ao inciso III do art. 497 e às hipóteses enumeradas. Não libera aquisição especulativa de bem litigioso.", "Coerdeiro", "pessoa que compartilha com outras o direito à mesma herança"),
    "499": row("Cônjuges podem comprar e vender entre si bens que não integrem a comunhão do casal.", "O negócio é admitido quando o bem pertence separadamente a um cônjuge e pode ingressar no patrimônio próprio do outro. Vender bem já comum seria incompatível com a estrutura patrimonial.", "Cônjuge vende ao outro imóvel particular excluído da comunhão pelo regime de bens.", "É indispensável verificar o regime matrimonial, a origem do bem e exigências de forma. A permissão não afasta fraude ou simulação.", "Bem excluído da comunhão", "bem que não integra o patrimônio comum dos cônjuges"),
    "500": row("Se imóvel vendido por medida tiver área diferente, o comprador pode exigir complemento, resolução ou abatimento; excesso pode exigir pagamento ou devolução. Referência enunciativa e venda de coisa certa recebem tratamento próprio.", "A solução varia conforme venda por extensão ou ad corpus, magnitude da diferença e conhecimento do vendedor. Diferença até um vigésimo presume indicação aproximada, admitida prova contrária.", "Terreno vendido por metro quadrado tem área menor; comprador busca complemento ou redução proporcional.", "As alternativas e os §§ 1º a 3º exigem apuração do modo de venda. A presunção de 5% não impede prova do interesse determinante.", "Venda ad corpus", "venda do imóvel como unidade certa, sendo secundária a indicação de área"),
    "501": row("Vendedor ou comprador perde em um ano o direito às medidas por diferença de área, contado do registro; atraso de posse atribuível ao alienante desloca o início para a imissão.", "O prazo decadencial estabiliza a venda imobiliária. Se o vendedor impede a entrada na posse, o interessado só começa a perder prazo quando efetivamente a recebe.", "Comprador obtém posse meses após o registro por atraso do vendedor; o ano começa na imissão.", "O artigo trata das ações do art. 500. É necessário provar a imputação do atraso ao alienante e identificar a data correta.", "Imissão na posse", "entrada efetiva e juridicamente reconhecida do adquirente no imóvel"),
    "502": row("Salvo pacto contrário, o vendedor responde pelos débitos que onerem a coisa até sua entrega.", "Encargos vinculados ao bem e formados antes da tradição ficam, por regra, com quem ainda era responsável por ele. O contrato pode redistribuir internamente esse custo.", "Vendedor quita encargo incidente sobre equipamento até o dia em que o entrega ao comprador.", "A cláusula entre as partes pode não alterar responsabilidade perante o credor do débito. Natureza do encargo e legislação especial precisam ser verificadas.", "Débito que grava a coisa", "obrigação vinculada economicamente ou juridicamente ao bem"),
    "503": row("Quando várias coisas são vendidas em conjunto, defeito oculto de uma delas não permite rejeitar todas.", "A resposta deve se concentrar no item defeituoso, preservando os demais, salvo se a unidade econômica do negócio ou outra regra justificar solução distinta.", "Lote de cinco máquinas inclui uma com vício oculto; o comprador não devolve automaticamente as cinco.", "É preciso avaliar se as coisas são separáveis e se o defeito compromete a finalidade conjunta. O artigo não elimina remédios relativos ao item viciado.", "Venda conjunta", "negócio que reúne várias coisas em uma mesma contratação"),
    "504": row("Condômino de coisa indivisível deve oferecer sua quota aos demais nas condições dadas ao estranho; omitida a ciência, outro consorte pode depositar o preço e requerer a parte em 180 dias.", "A preferência mantém a comunhão entre quem já a integra. Havendo vários interessados, prevalecem benfeitorias de maior valor, depois maior quinhão e, persistindo igualdade, aquisição conjunta.", "Coproprietário vende quota a terceiro sem avisar; outro deposita o preço e exerce preferência no prazo.", "Exigem-se indivisibilidade, igualdade de condições, depósito e prazo decadencial. Venda de coisa divisível não segue automaticamente esta regra.", "Tanto por tanto", "preferência exercida pelo mesmo preço e nas mesmas condições oferecidas ao terceiro"),
    "505": row("Na venda de imóvel, o vendedor pode reservar direito de retomá-lo em até três anos, devolvendo preço e reembolsando despesas previstas.", "A retrovenda cria faculdade resolutiva limitada no tempo. O resgate exige restituição do valor recebido e despesas do comprador, inclusive autorizadas por escrito ou relativas a benfeitorias necessárias.", "Vendedor exerce retrovenda dois anos depois e paga integralmente preço e despesas ressarcíveis.", "O prazo de três anos é máximo e decadencial. A cláusula só cabe para imóvel e não dispensa pagamento completo.", "Retrovenda", "cláusula que permite ao vendedor recomprar o imóvel nas condições legais"),
    "506": row("Se o comprador recusar os valores do resgate, o vendedor deve depositá-los judicialmente; depósito insuficiente impede a retomada até integral pagamento.", "A consignação preserva o exercício da retrovenda contra recusa injustificada, mas o comprador precisa receber tudo a que tem direito antes de perder o domínio.", "Comprador rejeita preço e despesas; vendedor deposita judicialmente a soma completa para resgatar o imóvel.", "Depósito meramente aproximado não basta. A insuficiência deve ser complementada antes da restituição do domínio.", "Direito de resgate", "faculdade do vendedor de recuperar o imóvel vendido com cláusula de retrovenda"),
    "507": row("O direito de retrovenda pode ser cedido, transmitido a herdeiros e legatários e exercido contra terceiro que adquiriu o imóvel.", "A faculdade acompanha seus sucessores e pode alcançar alienação posterior, preservando a eficácia real do pacto nas condições legais.", "Herdeiro do vendedor exerce o resgate contra pessoa que comprou o imóvel do adquirente original.", "O exercício continua sujeito a prazo, pagamento e publicidade ou oponibilidade pertinentes. Transmissão não amplia o conteúdo do direito.", "Direito de retrato", "direito de retomar o imóvel vendido mediante resgate nas condições pactuadas"),
    "508": row("Quando várias pessoas têm direito de retrovenda e apenas uma o exerce, o comprador pode intimar as demais; sem acordo, prevalece quem fizer depósito integral.", "A regra evita fracionamento indefinido do resgate e dá oportunidade aos cotitulares de atuar em conjunto. O pagamento completo define a preferência na falta de consenso.", "Dois herdeiros têm direito de retrato; um deposita todo o valor após intimação e prevalece.", "Depósito parcial não assegura a retomada. A intimação deve permitir que os demais se manifestem sobre o exercício comum.", "Cotitular", "pessoa que compartilha com outras a titularidade do mesmo direito"),
    "509": row("A venda a contento fica sob condição suspensiva até o comprador declarar que gostou da coisa, mesmo que já a tenha recebido.", "A entrega não aperfeiçoa definitivamente a compra. A satisfação subjetiva do adquirente, exercida conforme boa-fé, é o evento que libera os efeitos finais.", "Cliente recebe instrumento para avaliação e só confirma a compra após manifestar agrado.", "Venda a contento difere da venda sujeita a prova: aqui importa a satisfação do comprador, dentro dos limites do contrato e da boa-fé.", "Venda a contento", "venda condicionada à manifestação de satisfação do comprador"),
    "510": row("Na venda sujeita a prova, a condição suspensiva consiste em verificar se a coisa possui as qualidades prometidas e serve ao fim destinado.", "A aprovação segue critérios objetivos de conformidade e utilidade, não mero gosto pessoal. Enquanto não verificada, a compra permanece condicionada.", "Máquina é entregue para teste e só será aceita se alcançar a capacidade técnica assegurada.", "O comprador não pode rejeitar arbitrariamente coisa que cumpre qualidades e finalidade pactuadas. Prova e parâmetros contratuais são essenciais.", "Venda sujeita a prova", "venda condicionada à comprovação objetiva de qualidade e adequação"),
    "511": row("Quem recebe a coisa em venda a contento ou sujeita a prova deve guardá-la como comodatário até aceitá-la.", "Antes da aprovação, o comprador ainda não ocupa plenamente a posição definitiva e deve conservar e usar o bem com os cuidados de empréstimo gratuito.", "Pessoa testa equipamento e precisa preservá-lo, sem uso além do necessário, até decidir pela aceitação.", "A responsabilidade depende das regras do comodato e do comportamento concreto. Recebimento físico não significa aceitação tácita em toda situação.", "Comodatário", "quem recebe gratuitamente coisa para uso temporário e posterior devolução"),
    "512": row("Sem prazo para o comprador declarar aceitação, o vendedor pode notificá-lo judicial ou extrajudicialmente para decidir em período final e não prorrogável.", "A notificação encerra a indefinição da condição e obriga manifestação dentro de prazo assinado. Pode ser feita fora do processo, desde que comprovável.", "Vendedor envia notificação com prazo definitivo para comprador concluir teste e informar se aceita.", "O prazo deve permitir manifestação real conforme a natureza da prova. Silêncio e seus efeitos dependem do contrato e das regras aplicáveis.", "Prazo improrrogável", "período final que não admite extensão pela regra do artigo"),
    "513": row("A preferência obriga o comprador a oferecer primeiro ao antigo vendedor a coisa que pretende vender ou dar em pagamento, nas mesmas condições; o prazo máximo é 180 dias para móvel e dois anos para imóvel.", "A cláusula cria prioridade de recompra, não retorno automático do bem. O titular precisa igualar a proposta quando o adquirente decidir alienar.", "Comprador pretende vender imóvel e comunica preço e condições ao antigo vendedor para eventual preferência.", "Os limites do parágrafo único restringem o prazo contratual. Preferência não se confunde com retrovenda e depende de futura alienação.", "Preempção", "direito de ser preferido na aquisição em igualdade de condições"),
    "514": row("Ao saber que o comprador pretende alienar a coisa, o antigo vendedor pode tomar a iniciativa e intimá-lo para exercer a preferência.", "O titular não precisa aguardar passivamente a oferta formal quando possui notícia da venda planejada. A intimação documenta sua disposição de comprar nas condições pertinentes.", "Antigo vendedor descobre anúncio do bem e notifica o comprador para apresentar condições e respeitar sua prioridade.", "A iniciativa não elimina a necessidade de igualdade de preço e vantagens nem prolonga prazos já extintos.", "Direito de prelação", "prioridade para adquirir bem antes de terceiro em condições iguais"),
    "515": row("Quem exerce preferência deve pagar o preço obtido ou ajustado nas mesmas condições, sob pena de perder o direito.", "A prioridade não permite impor condição mais favorável ao preferente. Ele precisa igualar a proposta real do terceiro e cumprir o pagamento correspondente.", "Terceiro oferece pagamento à vista; o antigo vendedor só exerce preferência oferecendo o mesmo valor e condição.", "Devem ser consideradas também vantagens economicamente relevantes, não apenas o número nominal do preço. Simulação pode gerar responsabilidade.", "Condições iguais", "equivalência de preço, prazo e demais vantagens da proposta concorrente"),
    "516": row("Sem prazo contratual, a preferência caduca em três dias para móvel e sessenta dias para imóvel, contados da notificação do comprador.", "A comunicação inicia prazo curto para decisão, impedindo que o direito mantenha indefinidamente a alienação suspensa.", "Antigo vendedor é notificado sobre venda de imóvel e precisa exercer a preferência em até sessenta dias.", "A contagem pressupõe notificação com informações suficientes sobre preço e condições. Prazo contratual válido afasta estes prazos subsidiários.", "Caducidade", "extinção do direito por não ser exercido dentro do prazo aplicável"),
    "517": row("Preferência concedida conjuntamente a várias pessoas só pode ser exercida sobre a coisa inteira; se uma não a usar, as demais podem exercer o direito completo.", "O bem não é fracionado pela pluralidade de titulares. Os interessados atuantes podem assumir a aquisição integral nas mesmas condições.", "Três pessoas têm preferência comum; uma desiste e as outras compram conjuntamente a totalidade do bem.", "A regra depende de preferência estipulada em comum. A distribuição interna do preço e da aquisição deve ser ajustada entre os titulares.", "Preferência comum", "direito de prioridade atribuído conjuntamente a duas ou mais pessoas"),
    "518": row("Comprador que aliena sem informar ao preferente preço e vantagens responde por perdas e danos; o terceiro adquirente de má-fé responde solidariamente.", "A violação da preferência contratual gera reparação. O adquirente só compartilha a responsabilidade se conhecia a preferência e participou de modo incompatível com a boa-fé.", "Comprador vende escondendo proposta; antigo vendedor prova prejuízo, e terceiro consciente da preferência responde junto.", "O artigo prevê indenização, não aquisição automática da coisa. Dano, nexo e má-fé do terceiro precisam ser demonstrados.", "Responsabilidade solidária", "dever que permite cobrar de qualquer responsável a totalidade da indenização"),
    "519": row("Se bem desapropriado não receber o destino público que justificou a expropriação, o antigo proprietário tem preferência para adquiri-lo pelo valor atual.", "A regra protege o expropriado diante de desvio de destinação, permitindo recompra prioritária, mas não retorno gratuito pelo preço histórico.", "Terreno desapropriado para escola não é usado em obra pública; o expropriado pede preferência pelo preço atual.", "Devem ser verificados destino efetivo, finalidade pública alternativa e regime jurídico da desapropriação. O artigo estabelece preferência, não nulidade automática.", "Retrocesso", "situação em que bem desapropriado não recebe a destinação pública prevista"),
    "520": row("O direito de preferência contratual não pode ser cedido e não é transmitido aos herdeiros.", "A preempção tem caráter pessoal: somente o titular originalmente favorecido pode exercê-la enquanto vigente.", "Antigo vendedor falece antes da revenda; seus herdeiros não assumem a preferência pactuada em favor dele.", "A intransmissibilidade deste artigo não deve ser confundida com o direito de retrovenda, que possui regra expressa de cessão e sucessão.", "Direito personalíssimo", "direito ligado à pessoa do titular e não transferível a terceiros"),
}
